public int equilibriumIndex(int[] nums) {
    long total = 0;
    for (int x : nums) {
        total += x;
    }
    long leftSum = 0;
    for (int i = 0; i < nums.length; i++) {
        long rightSum = total - leftSum - nums[i];
        if (leftSum == rightSum) {
            return i;
        }
        leftSum += nums[i];   // update AFTER the check
    }
    return -1;
}

