def equilibrium_index(self, nums: list[int]) -> int:
    total = sum(nums)
    left_sum = 0
    for i, x in enumerate(nums):
        right_sum = total - left_sum - x
        if left_sum == right_sum:
            return i
        left_sum += x          # update AFTER the check
    return -1

